module.exports = "<section class=\"feedback-page\">\n  <div class=\"container feedback-card\">\n    <span class=\"eyebrow\">{{ t('eyebrow') }}</span>\n    <h1>{{ t('title') }}</h1>\n    <p class=\"intro\">{{ t('intro') }}</p>\n\n    <div class=\"state-card\" *ngIf=\"!loggedUser\">\n      <p>{{ t('loginRequired') }}</p>\n      <a routerLink=\"/login\" class=\"btn btn-primary\">{{ t('login') }}</a>\n    </div>\n\n    <form class=\"feedback-form\" *ngIf=\"loggedUser\" (ngSubmit)=\"saveFeedback()\">\n      <div class=\"form-head full\">\n        <h2>{{ t('formTitle') }}</h2>\n        <p>{{ t('formIntro') }}</p>\n      </div>\n\n      <div class=\"state-card full\" *ngIf=\"shouldBlockNewFeedback() && !hasAnyEligibleOuting()\">\n        <p>{{ t('noEligibleBookings') }}</p>\n        <button class=\"btn btn-secondary\" type=\"button\" (click)=\"openNoFeedbackModal()\">\n          {{ t('noFeedbackModalTitle') }}\n        </button>\n      </div>\n\n      <label class=\"full\" *ngIf=\"availableFeedbackBookings().length > 0\">\n        <span>{{ t('outing') }}</span>\n        <select name=\"bookingId\" [(ngModel)]=\"feedback.bookingId\" (ngModelChange)=\"selectFeedbackBooking($event)\" required>\n          <option value=\"\" disabled>{{ 'auto.home.my-feedbacks.my-feedbacks.component.select_an_outing' | siteText }}</option>\n          <option *ngFor=\"let booking of availableFeedbackBookings()\" [value]=\"booking.bookingId\">\n            {{ feedbackBookingLabel(booking) }}\n          </option>\n        </select>\n      </label>\n\n      <label>\n        <span>{{ t('formDate') }}</span>\n        <input type=\"date\" name=\"date\" [(ngModel)]=\"feedback.date\" readonly required />\n      </label>\n\n      <label>\n        <span>{{ t('time') }}</span>\n        <input type=\"time\" name=\"time\" [(ngModel)]=\"feedback.time\" readonly required />\n      </label>\n\n      <label class=\"full\">\n        <span>{{ t('outingType') }}</span>\n        <input type=\"text\" name=\"outingType\" [(ngModel)]=\"feedback.outingType\" readonly required />\n      </label>\n\n      <label class=\"full\">\n        <span>{{ t('rating') }}</span>\n        <div class=\"rating-buttons\" role=\"radiogroup\" [attr.aria-label]=\"t('rating')\">\n          <button\n            type=\"button\"\n            *ngFor=\"let value of [1,2,3,4,5]\"\n            [class.active]=\"feedback.rating === value\"\n            (click)=\"setRating(value)\"\n            [attr.aria-pressed]=\"feedback.rating === value\">\n            {{ value }} ★\n          </button>\n        </div>\n      </label>\n\n      <label class=\"full\">\n        <span>{{ t('comments') }}</span>\n        <textarea name=\"comments\" rows=\"5\" [(ngModel)]=\"feedback.comments\" required></textarea>\n      </label>\n\n      <div class=\"form-actions full\">\n        <button class=\"btn btn-primary\" type=\"submit\" [disabled]=\"saving || availableFeedbackBookings().length === 0\">\n          {{ saving ? t('saving') : t('save') }}\n        </button>\n      </div>\n\n      <p class=\"success full\" *ngIf=\"saved\">{{ t('saved') }}</p>\n      <p class=\"error full\" *ngIf=\"saveError\">{{ saveError }}</p>\n    </form>\n\n    <div class=\"feedback-list\" *ngIf=\"loggedUser\">\n      <h2>{{ t('listTitle') }}</h2>\n\n      <div class=\"state-card\" *ngIf=\"loading\">\n        <p>{{ t('loading') }}</p>\n      </div>\n\n      <p class=\"error\" *ngIf=\"error\">{{ error }}</p>\n      <p class=\"success\" *ngIf=\"editSaved\">{{ editSaved }}</p>\n      <p class=\"error\" *ngIf=\"editError\">{{ editError }}</p>\n\n      <div class=\"state-card\" *ngIf=\"!loading && !error && feedbacks.length === 0\">\n        <p>{{ t('empty') }}</p>\n      </div>\n\n      <div class=\"feedback-grid\" *ngIf=\"!loading && feedbacks.length > 0\">\n        <article class=\"feedback-item\" *ngFor=\"let item of feedbacks\">\n          <ng-container *ngIf=\"editingFeedbackId !== feedbackId(item); else editBlock\">\n            <div class=\"feedback-topline\">\n              <strong>{{ item.outingType || '-' }}</strong>\n              <span class=\"stars\">{{ stars(item.rating || item.rate) }}</span>\n            </div>\n\n            <div class=\"feedback-meta\">\n              <span>{{ t('date') }}: {{ item.date || '-' }}</span>\n              <span>{{ t('time') }}: {{ item.time || '-' }}</span>\n            </div>\n\n            <p class=\"feedback-comment\">{{ displayComment(item) }}</p>\n\n            <div class=\"feedback-actions\">\n              <button type=\"button\" class=\"btn btn-secondary\" (click)=\"startEdit(item)\">\n                {{ t('edit') }}\n              </button>\n\n              <button\n                type=\"button\"\n                class=\"btn btn-danger\"\n                (click)=\"deleteFeedback(item)\"\n                [disabled]=\"deletingFeedbackId === feedbackId(item)\">\n                {{ t('delete') }}\n              </button>\n            </div>\n          </ng-container>\n\n          <ng-template #editBlock>\n            <form class=\"feedback-form edit-form\" (ngSubmit)=\"updateExistingFeedback(item)\">\n              <label>\n                <span>{{ t('formDate') }}</span>\n                <input type=\"date\" name=\"editDate{{ feedbackId(item) }}\" [(ngModel)]=\"editFeedback.date\" readonly required />\n              </label>\n\n              <label>\n                <span>{{ t('time') }}</span>\n                <input type=\"time\" name=\"editTime{{ feedbackId(item) }}\" [(ngModel)]=\"editFeedback.time\" readonly required />\n              </label>\n\n              <label class=\"full\">\n                <span>{{ t('outingType') }}</span>\n                <input type=\"text\" name=\"editOutingType{{ feedbackId(item) }}\" [(ngModel)]=\"editFeedback.outingType\" readonly required />\n              </label>\n\n              <label class=\"full\">\n                <span>{{ t('rating') }}</span>\n                <div class=\"rating-buttons\" role=\"radiogroup\" [attr.aria-label]=\"t('rating')\">\n                  <button\n                    type=\"button\"\n                    *ngFor=\"let value of [1,2,3,4,5]\"\n                    [class.active]=\"editFeedback.rating === value\"\n                    (click)=\"setEditRating(value)\"\n                    [attr.aria-pressed]=\"editFeedback.rating === value\">\n                    {{ value }} ★\n                  </button>\n                </div>\n              </label>\n\n              <label class=\"full\">\n                <span>{{ t('comments') }}</span>\n                <textarea name=\"editComments{{ feedbackId(item) }}\" rows=\"4\" [(ngModel)]=\"editFeedback.comments\" required></textarea>\n              </label>\n\n              <div class=\"form-actions full edit-actions\">\n                <button class=\"btn btn-primary\" type=\"submit\" [disabled]=\"saving\">\n                  {{ saving ? t('saving') : t('update') }}\n                </button>\n                <button class=\"btn btn-secondary\" type=\"button\" (click)=\"cancelEdit()\">\n                  {{ t('cancel') }}\n                </button>\n              </div>\n            </form>\n          </ng-template>\n        </article>\n      </div>\n    </div>\n\n    <div class=\"feedback-modal-backdrop\" *ngIf=\"noFeedbackModalOpen\" (click)=\"closeNoFeedbackModal()\">\n      <section class=\"feedback-modal\" (click)=\"$event.stopPropagation()\">\n        <button class=\"modal-close\" type=\"button\" (click)=\"closeNoFeedbackModal()\">×</button>\n        <span class=\"eyebrow\">{{ t('eyebrow') }}</span>\n        <h2>{{ t('noFeedbackModalTitle') }}</h2>\n        <p>{{ t('noFeedbackModalText') }}</p>\n        <div class=\"modal-actions\">\n          <button class=\"btn btn-primary\" type=\"button\" (click)=\"closeNoFeedbackModal()\">\n            {{ t('noFeedbackModalClose') }}\n          </button>\n        </div>\n      </section>\n    </div>\n\n  </div>\n</section>\n";

