module.exports = "<section class=\"external-bookings-page\">\n  <div class=\"container external-shell\">\n    <div class=\"section-head\" *ngIf=\"!embedded\">\n      <span class=\"eyebrow\">{{ t('eyebrow') }}</span>\n      <h1>{{ t('title') }}</h1>\n      <p>{{ t('intro') }}</p>\n      <p class=\"archive-notice\" *ngIf=\"isHistoricalMode\">{{ t('archiveOnlyNotice') }}</p>\n    </div>\n\n    <article class=\"external-card\">\n      <h2>{{ t('boat') }}</h2>\n      <div class=\"form-grid\">\n        <label>{{ t('boat') }}\n          <select [(ngModel)]=\"selectedBoatId\" (ngModelChange)=\"onBoatSelected($event)\">\n            <option *ngFor=\"let boat of boats\" [value]=\"boat.boatId\">{{ boat.boatName }} — {{ boat.model || boat.boatType }}</option>\n          </select>\n        </label>\n\n        <label class=\"computed-field\">{{ t('boatName') }}\n          <input type=\"text\" readonly [(ngModel)]=\"form.boatName\" />\n          <small>{{ t('calculatedField') }}</small>\n        </label>\n\n        <label class=\"computed-field\">{{ t('boatType') }}\n          <input type=\"text\" readonly [(ngModel)]=\"form.boatType\" />\n          <small>{{ t('calculatedField') }}</small>\n        </label>\n\n        <label class=\"computed-field\">{{ t('boatManufacturer') }}\n          <input type=\"text\" readonly [(ngModel)]=\"form.boatManufacturer\" />\n          <small>{{ t('calculatedField') }}</small>\n        </label>\n\n        <label class=\"computed-field\">{{ t('boatModel') }}\n          <input type=\"text\" readonly [(ngModel)]=\"form.boatModel\" />\n          <small>{{ t('calculatedField') }}</small>\n        </label>\n\n        <label class=\"boat-url-line\">{{ t('boatListingUrl') }}\n          <input type=\"url\" [(ngModel)]=\"form.boatClickAndBoatUrl\" />\n          <a *ngIf=\"form.boatClickAndBoatUrl\" [href]=\"form.boatClickAndBoatUrl\" target=\"_blank\" rel=\"noopener\">{{ 'auto.home.admin-external-bookings.admin-external-bookings.component.open_listing' | siteText }}</a>\n        </label>\n\n        <label>{{ t('startMarina') }}\n          <select [(ngModel)]=\"form.startMarina\">\n            <option *ngFor=\"let marina of departureMarinas\" [value]=\"marina\">{{ marina }}</option>\n          </select>\n        </label>\n      </div>\n\n      <h2>{{ sourceSectionTitle }}</h2>\n      <div class=\"form-grid\">\n        <label>{{ t('entryMode') }}\n          <select [(ngModel)]=\"form.entryMode\">\n            <option [value]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.future' | siteText\">{{ t('futureMode') }}</option>\n            <option [value]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.historical' | siteText\">{{ t('historicalMode') }}</option>\n            <option [value]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.proposal' | siteText\">{{ t('clientProposalMode') }}</option>\n          </select>\n        </label>\n\n        <label>{{ t('platform') }}\n          <select [(ngModel)]=\"form.source\" (ngModelChange)=\"onPlatformChanged()\">\n            <option [value]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.direct' | siteText\">{{ t('platformDirect') }}</option>\n            <option [value]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.clickandboat' | siteText\">{{ t('platformClickAndBoat') }}</option>\n            <option [value]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.samboat' | siteText\">{{ t('platformSamboat') }}</option>\n            <option [value]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.other' | siteText\">{{ t('platformOther') }}</option>\n          </select>\n        </label>\n\n        <label *ngIf=\"isOtherSource\">{{ t('otherPlatformName') }}\n          <input type=\"text\" [(ngModel)]=\"form.externalPlatformName\" [placeholder]=\"t('otherPlatformNamePlaceholder')\" />\n        </label>\n\n        <ng-container *ngIf=\"!isDirectSource\">\n          <label>{{ platformReferenceLabel }}\n            <input type=\"text\" [(ngModel)]=\"form.externalPlatformBookingRef\" [placeholder]=\"platformReferenceLabel\" />\n          </label>\n\n          <label>{{ t('externalPlatformListingName') }}\n            <input type=\"text\" [(ngModel)]=\"form.externalPlatformListingName\" [placeholder]=\"platformDisplayName + ' listing name'\" />\n          </label>\n\n          <label>{{ platformListingUrlLabel }}\n            <input type=\"url\" [(ngModel)]=\"form.externalPlatformUrl\" [placeholder]=\"'https://...'\" />\n            <a *ngIf=\"form.externalPlatformUrl\" [href]=\"form.externalPlatformUrl\" target=\"_blank\" rel=\"noopener\">{{ 'auto.home.admin-external-bookings.admin-external-bookings.component.open_listing' | siteText }}</a>\n          </label>\n\n          <label>{{ platformBookingUrlLabel }}\n            <input type=\"url\" [(ngModel)]=\"form.platformBookingUrl\" [placeholder]=\"'https://...'\" />\n            <a *ngIf=\"form.platformBookingUrl\" [href]=\"form.platformBookingUrl\" target=\"_blank\" rel=\"noopener\">{{ 'auto.home.admin-external-bookings.admin-external-bookings.component.open_booking' | siteText }}</a>\n          </label>\n        </ng-container>\n      </div>\n\n      <h2>{{ t('customerName') }}</h2>\n      <div class=\"form-grid\">\n        <label>{{ t('customerName') }}<input type=\"text\" [(ngModel)]=\"form.customerName\" /></label>\n        <label>{{ t('customerEmail') }}<input type=\"email\" [(ngModel)]=\"form.customerEmail\" /></label>\n        <label>{{ t('phone') }}<input type=\"tel\" [(ngModel)]=\"form.customerPhone\" /></label>\n        <label>{{ t('passengers') }}<input type=\"number\" min=\"0\" step=\"1\" [(ngModel)]=\"form.passengers\" /></label>\n        <label>{{ t('outingType') }}<input type=\"text\" [(ngModel)]=\"form.outingType\" /></label>\n        <label>{{ t('outingDate') }}<input type=\"date\" [min]=\"outingDateMin\" [max]=\"outingDateMax\" [(ngModel)]=\"form.outingDate\" /><small>{{ outingDateHint }}</small></label>\n        <label>{{ t('departureTime') }}<input type=\"time\" [(ngModel)]=\"form.departureTime\" /></label>\n        <label>{{ t('returnTime') }}<input type=\"time\" [(ngModel)]=\"form.arrivalTime\" /></label>\n      </div>\n\n      <h2>{{ customerCostTitle }}</h2>\n      <div class=\"form-grid\">\n        <label *ngIf=\"isHistoricalMode\">{{ isDirectSource ? t('totalCollectedHistorical') : 'Total cost to client' }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.totalAmount\" /></label>\n\n        <ng-container *ngIf=\"!isDirectSource\">\n          <label>{{ platformCustomerAmountLabel }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.externalPlatformTotalClientAmount\" /></label>\n          <label>{{ platformPayoutLabel }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.externalPlatformPaidAmount\" /></label>\n          <label>{{ t('externalPlatformNetOwnerAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.externalPlatformNetOwnerAmount\" /></label>\n          <label>{{ t('externalPlatformRemainingOwnerAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.externalPlatformRemainingOwnerAmount\" /></label>\n          <label>{{ t('externalPortAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.externalPortAmount\" /></label>\n        </ng-container>\n      </div>\n\n      <h2>{{ alegriaCollectionsTitle }}</h2>\n      <div class=\"form-grid\">\n        <label>{{ t('skipperCashAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.skipperCashAmount\" /></label>\n        <label>{{ t('cleaningCashAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.cleaningCashAmount\" /></label>\n        <label>{{ t('cateringAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.cateringAmount\" /></label>\n        <label>{{ t('drinksAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.drinksAmount\" /></label>\n        <label>{{ t('waterToysAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.waterToysAmount\" /></label>\n        <label>{{ t('tipsAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.tipsAmount\" /></label>\n        <label>{{ t('otherOnboardAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.otherOnboardAmount\" /></label>\n\n        <label class=\"computed-field\">{{ isHistoricalMode ? t('notCollectedHistorical') : t('payableOnlineTotal') }}\n          <input type=\"number\" readonly [value]=\"isHistoricalMode ? 0 : payableOnlineTotal\" />\n          <small>{{ t('calculatedField') }}</small>\n        </label>\n        <label class=\"computed-field\">{{ isHistoricalMode ? t('notCollectedHistorical') : t('cashOnBoardTotal') }}\n          <input type=\"number\" readonly [value]=\"isHistoricalMode ? 0 : cashOnBoardTotal\" />\n          <small>{{ t('calculatedField') }}</small>\n        </label>\n        <label class=\"computed-field\">{{ isHistoricalMode ? t('notCollectedHistorical') : t('remainingTotal') }}\n          <input type=\"number\" readonly [value]=\"isHistoricalMode ? 0 : remainingTotal\" />\n          <small>{{ t('calculatedField') }}</small>\n        </label>\n        <label>{{ t('warrantyAmount') }}<input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"form.warrantyAmount\" /></label>\n\n        <label>{{ t('warrantyMethod') }}\n          <select [(ngModel)]=\"form.warrantyPaymentChoice\">\n            <option [value]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.stripe_card' | siteText\">{{ t('warrantyStripeCard') }}</option>\n            <option [value]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.cash_on_board' | siteText\">{{ t('warrantyCash') }}</option>\n          </select>\n        </label>\n      </div>\n\n      <label class=\"full-width\">{{ t('externalDocuments') }}\n        <textarea rows=\"4\" [(ngModel)]=\"form.externalDocuments\" [placeholder]=\"'auto.home.admin-external-bookings.admin-external-bookings.component.rachat_caution_facture_damage_waiver_conditions' | siteText\"></textarea>\n      </label>\n\n      <div class=\"actions\">\n        <button class=\"btn btn-primary\" type=\"button\" [disabled]=\"saving\" (click)=\"form.entryMode === 'proposal' ? saveExternalBooking() : saveManualHistoricalBooking()\">\n          {{ saving ? t('saving') : (form.entryMode === 'proposal' ? t('createClientProposal') : t('manualBookingSavedMessage')) }}\n        </button>\n      </div>\n\n      <p class=\"success\" *ngIf=\"message\">{{ message }}</p>\n      <p class=\"client-link\" *ngIf=\"createdBookingId\">\n        <a [routerLink]=\"['/admin/bookings', createdBookingId]\">{{ 'auto.home.admin-external-bookings.admin-external-bookings.component.ouvrir_la_r_servation_cr_e' | siteText }}</a>\n      </p>\n      <p class=\"client-link\" *ngIf=\"warrantyLink\">{{ t('clientProposalLink') }}: {{ warrantyLink }}</p>\n      <p class=\"error\" *ngIf=\"error\">{{ error }}</p>\n    </article>\n\n    <article class=\"external-card platform-bookings-list\" *ngIf=\"!embedded && platformBookings.length\">\n      <h2>{{ 'auto.home.admin-external-bookings.admin-external-bookings.component.r_servations' | siteText }}</h2>\n      <button class=\"platform-booking-row\" type=\"button\" *ngFor=\"let booking of platformBookings\" (click)=\"openBooking(booking)\">\n        <span><strong>{{ booking.customerName || '-' }}</strong><small>{{ booking.email || '-' }}</small></span>\n        <span><strong>{{ booking.externalPlatformName || booking.externalPlatform || booking.source || 'Direct Alegria' }}</strong><small>{{ booking.externalPlatformBookingRef || booking.platformBookingReference || (booking.source === 'direct' ? 'Direct' : '-') }}</small></span>\n        <span><strong>{{ booking.outingDate }}</strong><small>{{ booking.departureTime }} - {{ booking.arrivalTime }}</small></span>\n        <span><strong>{{ booking.totalPrice | currency:'EUR':'symbol':'1.0-2' }}</strong><small>{{ 'auto.home.admin-external-bookings.admin-external-bookings.component.restant_alegria' | siteText }}</small></span>\n      </button>\n    </article>\n  </div>\n</section>\n";

